"""保存した制約を読む作例と、論文の結果を別々に表示する。"""
import json


def widget(results):
    if not isinstance(results, dict) or results.get('lab_kind') != 'forgetting05':
        return ''
    data = json.dumps(results, ensure_ascii=False).replace('<', '\\u003c')
    return r'''<section class="forget05" aria-label="推論を消すと、制約を求め直す回数はどう変わるか">
<style>
.forget05{--f:#336a65;background:#f1f5f2;padding:clamp(12px,3vw,28px);border-radius:16px;color:#163a38}.forget05 *{box-sizing:border-box}.forget05 .carriers{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.forget05 .carrier{background:white;border-top:4px solid var(--f);padding:14px;border-radius:6px}.forget05 select,.forget05 input{max-width:100%;font:inherit}.forget05 select{width:100%;padding:10px}.forget05 .trace{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:16px 0}.forget05 .step{padding:10px;background:white;border-left:4px solid #64847b}.forget05 .step.lost{border-color:#b55634;background:#fff2e9}.forget05 .step.disk{border-color:#346eb1}.forget05 svg{width:100%;height:auto;background:white;border-radius:8px}.forget05 .equation{padding:15px;background:white;font-family:monospace;overflow-wrap:anywhere}.forget05 figcaption{font-size:.9rem}.forget05 label{display:block;margin:12px 0}.forget05 output{font-weight:700}.forget05 .risk{display:flex;gap:14px;flex-wrap:wrap}.forget05 .risk p{flex:1;min-width:160px;padding:12px;background:#fff}.forget05 .risk strong{display:block;font-size:1.8rem}@media(max-width:600px){.forget05 .carriers,.forget05 .trace{grid-template-columns:1fr}.forget05 svg text{font-size:15px}}
</style>
<h3>Lab の作例：前に決めた制約を後で読めるか</h3>
<div class="carriers"><div class="carrier"><b>推論 R</b><p>モデルがまだ作業に反映していない判断を残す。</p></div><div class="carrier"><b>コード / ファイル Z</b><p>前に決めた制約を、後から読める形で残す。</p></div><div class="carrier"><b>観測 O</b><p>ツールが返した情報を残す。次の処理で読めれば、取り直さずに済む。</p></div></div>
<p>モデルが推論以外の記録を使うには、必要な情報が保存されていて、その記録を後から読める必要がある。</p>
<label>作例で残す記録を選ぶ<select data-case><option value="keep">推論を残す</option><option value="prune_internal">推論だけを削る</option><option value="prune_external">ファイルに保存してから推論を消す</option><option value="prune_unreadable">ファイルに保存して推論を消すが、後でファイルを読めない</option></select></label>
<div class="trace" data-trace></div><p data-summary aria-live="polite"></p>
<p>作例では、推論を参照する費用を 1、ファイルを読む費用を 2、計算し直す費用を 10 とした。これはトークン数ではない。どの条件でも、6 回の要求に返す値は同じになる。</p>
<h3>論文の観察：31 課題の途中で得た 265 場面</h3><div class="risk" data-risk></div>
<p>表 14 は、後の作業で推論を追加したり、制約を求め直したり、計画を立て直したりした割合を示す。群全体の差は 31.16 ポイントだが、同じ課題内で比べた差は 19.75 ポイントで、95% 区間は 1.00〜37.05 だった（表 15）。記録の保存先を無作為に変えて測った効果ではない。</p>
<figure><h3>その場で多く消しても、作業全体の入力が大きく減るとは限らない</h3><svg viewBox="0 0 560 330" role="img" aria-label="推論を無作為に消した割合と、作業全体の入力が減った割合" data-scatter></svg><figcaption>著者が 80 課題で推論を無作為に消したときの結果を示す（表 10、図 3）。段落を選ぶ ICLR の点は含まない。この図から最適な削除率は求めていない。</figcaption></figure>
<h3>次に選ぶ行動の差が積み重なると、作業全体はどこまで変わるか</h3><label>同じ履歴を読んだ 2 条件で、次の行動の分布がどこまで違うか（上限 ε） <input data-e type="range" min="0" max="0.1" step="0.005" value="0.02"></label><label>行動を選ぶ回数 K <input data-k type="range" min="1" max="100" value="30"></label><div class="equation" data-bound aria-live="polite"></div><p>TV は 2 つの確率分布の違いを表す。ここでは、入力した ε と K を使い、論文の定理 B.3 の仮定のもとで作業全体の差の上限を計算する。実験で測ったリスクではなく、予測エントロピーから ε を推定する式でもない。</p>
<script type="application/json" data-forget>''' + data + r'''</script>
<script>(()=>{const root=document.currentScript.parentElement,d=JSON.parse(root.querySelector('[data-forget]').textContent),sel=root.querySelector('[data-case]');function show(){const c=d.cases[sel.value],names={'reasoning':'推論を参照','read-file':'ファイルを読む','rederive':'制約を求め直す'};root.querySelector('[data-trace]').innerHTML=c.trace.map((t,i)=>`<div class="step ${t.action==='rederive'?'lost':t.action==='read-file'?'disk':''}"><b>${i+1}. ${t.key}</b><br>${names[t.action]}<br>値 ${t.value} ／ 労力 ${t.effort}</div>`).join('');root.querySelector('[data-summary]').textContent=`求め直した回数：${c.rederivations} 回。ファイルから読んだ回数：${c.file_reads} 回。作例内の費用：${c.effort_units}。`;}sel.addEventListener('change',show);show();root.querySelector('[data-risk]').innerHTML=d.paper.risk.map(x=>`<p>${x.group}<strong>${x.percent}%</strong>${x.n} 場面</p>`).join('');const x=v=>65+v*10,y=v=>265-v*3;let s='<text x="65" y="23">作業全体の入力が減った割合（%）</text><path d="M65 45 V265 H500" fill="none" stroke="#456"/>';[0,20,40,60].forEach(v=>s+=`<text x="25" y="${y(v)+5}">${v}</text><path d="M65 ${y(v)}H500" stroke="#ddd"/>`);[0,10,20,30,40].forEach(v=>s+=`<text x="${x(v)-7}" y="287">${v}</text>`);d.paper.random.forEach(p=>s+=`<circle cx="${x(p.delete)}" cy="${y(p.input_reduction)}" r="7" fill="#b55634"/><text x="${x(p.delete)+9}" y="${y(p.input_reduction)-10}">${p.input_reduction}%</text>`);s+='<text x="150" y="318">その場で消した推論トークンの割合（%）</text>';root.querySelector('[data-scatter]').innerHTML=s;function bound(){let e=+root.querySelector('[data-e]').value,k=+root.querySelector('[data-k]').value;root.querySelector('[data-bound]').textContent=`ε=${e.toFixed(3)}, K=${k} → TV ≤ 1−(1−ε)^K = ${(1-(1-e)**k).toFixed(3)} ≤ min(1,Kε) = ${Math.min(1,k*e).toFixed(3)}`;}root.querySelector('[data-e]').addEventListener('input',bound);root.querySelector('[data-k]').addEventListener('input',bound);bound();})();</script></section>'''
